import functools
from typing import ForwardRef, get_type_hints
from fastapi.dependencies.utils import get_typed_signature, get_typed_annotation

class A:
    def method(self, x: "B") -> "B":
        return x

class B:
    pass

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

# Wrap the method
wrapped_method = wrapper(A().method)

# This should work with typing.get_type_hints
try:
    hints = get_type_hints(wrapped_method)
    print("get_type_hints success")
except Exception as e:
    print(f"get_type_hints failed: {e}")

# This should fail with current fastapi.dependencies.utils.get_typed_signature
try:
    sig = get_typed_signature(wrapped_method)
    print("get_typed_signature success")
    for param in sig.parameters.values():
        print(f"Param {param.name}: {param.annotation}")
except Exception as e:
    print(f"get_typed_signature failed: {e}")
    import traceback
    traceback.print_exc()

