import inspect

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

# Wrap the method from module_a
wrapped_method = wrapper(module_a.A().method)

sig = inspect.signature(wrapped_method)
print(f"Original annotation: {sig.parameters['x'].annotation}")
print(f"Annotation type: {type(sig.parameters['x'].annotation)}")

try:
    typed_sig = get_typed_signature(wrapped_method)
    print(f"Typed annotation: {typed_sig.parameters['x'].annotation}")
except Exception as e:
    print(f"get_typed_signature failed: {e}")

