import functools
from typing import ForwardRef, get_type_hints
from fastapi.dependencies.utils import get_typed_signature, get_typed_return_annotation

def original_func(a: "MyType") -> "MyType":
    return a

class MyType:
    pass

# Wrap the function
@functools.wraps(original_func)
def wrapper(a: "MyType") -> "MyType":
    return original_func(a)

def test_get_typed_signature():
    print("Testing get_typed_signature...")
    try:
        sig = get_typed_signature(wrapper)
        param_annotation = sig.parameters['a'].annotation
        print(f"Param annotation: {param_annotation}")
        assert param_annotation is MyType
        print("SUCCESS")
    except Exception as e:
        print(f"FAILED: {e}")

def test_get_typed_return_annotation():
    print("Testing get_typed_return_annotation...")
    try:
        ret_annotation = get_typed_return_annotation(wrapper)
        print(f"Return annotation: {ret_annotation}")
        assert ret_annotation is MyType
        print("SUCCESS")
    except Exception as e:
        print(f"FAILED: {e}")

if __name__ == "__main__":
    test_get_typed_signature()
    test_get_typed_return_annotation()

